using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class KnockdownChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void Verify(){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var site=god.GetComponent<CreatureConstructionLearning>().sites[0];var ball=slice.GetComponentInChildren<BeachBall>();var nav=god.GetComponent<IslandNavigator>().world;Require(!nav.TreeNavigationPending,"Wait for navigation");var field=typeof(QuestSlice).GetField("state",Flags);var original=field.GetValue(slice);var geometry=site.Capture();var recipe=site.Recipe;bool paused=site.Paused;var actors=slice.GetComponentsInChildren<VillagerSocial>();var actorAt=actors.Select(a=>a.transform.position).ToArray();var godAt=god.transform.position;var active=site.blocks.Select(b=>b.gameObject.activeSelf).ToArray();var physicsActive=site.blocks.Select(b=>b.Body.gameObject.activeSelf).ToArray();var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100};var item=ball.GetComponent<CarryItem>();
  void Isolate(ConstructionBlock target){ball.ReturnHome();site.ResetConstruction();for(int i=0;i<site.blocks.Count;i++){var b=site.blocks[i];bool visible=b==target;b.gameObject.SetActive(visible);b.Body.gameObject.SetActive(visible);}site.Paused=false;}
  void Launch(ConstructionBlock target,float speed){var center=site.World(target.Body.position);var direction=site.transform.right;ball.transform.position=center-direction*(ball.Radius+target.size.x*.5f+.8f)*nav.Scale;var at=ball.transform.position;at.y=Mathf.Max(at.y,site.transform.position.y+ball.Radius*nav.Scale+.05f*nav.Scale);ball.transform.position=at;ball.Throw(direction,false,speed);ball.Body.linearVelocity=direction*speed;}
  void Step(){test.Hybrid.time+=.02f;ball.Advance(.02f,false);site.Advance(.02f);}
  try{
   god.Interrupt("Knockdown QA");field.SetValue(slice,test);god.NewSeason();foreach(var a in actors){a.ResetTask();a.GetComponent<VillagerExploration>().ResetTask();a.GetComponent<VillagerResourceGathering>().Cancel();a.GetComponent<VillagerBlockPlay>().ResetTask();a.transform.position+=Vector3.up*nav.Scale*500;}god.transform.position+=Vector3.up*nav.Scale*500;
   var block=site.blocks.First(b=>b.Shape==ConstructionShape.Cube);Isolate(block);var at=new Vector3(0,block.size.y*.5f,-12);Require(site.Drop(block,site.World(at),site.transform.rotation),"Cube snap failed");site.Detach(block);var before=block.Body.position;Launch(block,5);for(int i=0;i<160&&(block.Body.position-before).sqrMagnitude<.02f;i++)Step();Require(block.Body.position.x>before.x+.1f,"Gentle native contact did not push loose block: "+block.Body.position+" ball="+ball.Body.position+" velocity="+ball.Body.linearVelocity);var contacts=(BallBlockProxy[])typeof(BeachBall).GetField("blockContacts",Flags).GetValue(ball);Require(contacts.Length==16&&contacts.Count(c=>c.gameObject.activeSelf)<=16,"Contact pool unbounded");
   Isolate(block);Require(site.Drop(block,site.World(at),site.transform.rotation),"Gentle snap stage failed");Launch(block,5);for(int i=0;i<100;i++)Step();Require(block.Attached,"Gentle contact broke a snapped piece");
   Isolate(block);Require(site.Drop(block,site.World(at),site.transform.rotation,true),"Hard snap stage failed");Launch(block,24);for(int i=0;i<100&&block.Attached;i++)Step();Require(!block.Attached,"Hard native collision did not detach snapped piece");for(int i=0;i<10;i++)Step();Require(Vector3.Distance(block.Body.position,at)>.1f,"Knocked block did not move");var snapshot=site.Capture();Require(ConstructionSite.Valid(snapshot)&&snapshot[site.blocks.IndexOf(block)].support== -2,"Knockdown geometry did not capture detached state");site.Restore(snapshot);Require(!block.Attached,"Restore reattached knocked block");
   Isolate(block);Require(site.Drop(block,site.World(at),site.transform.rotation),"Held stage failed");block.Item.held=true;block.Grab();before=block.Body.position;Launch(block,24);for(int i=0;i<40;i++)ball.Advance(.02f,false);Require(block.Body.isKinematic&&block.Body.position==before&&contacts.All(c=>c.Block!=block||!c.gameObject.activeSelf),"Held piece was struck");block.Item.held=false;
   Isolate(block);Require(site.Drop(block,site.World(at),site.transform.rotation),"Pause stage failed");Launch(block,24);before=block.Body.position;var ballBefore=ball.Body.position;ball.Advance(1,true);site.Paused=true;site.Advance(1);Require(block.Attached&&block.Body.position==before&&ball.Body.position==ballBefore,"Paused physics advanced");site.Paused=false;
   Isolate(block);Require(site.Drop(block,site.World(at),site.transform.rotation),"Carried ball stage failed");Launch(block,24);item.held=true;ball.Advance(.02f,false);Require(contacts.All(c=>!c.gameObject.activeSelf)&&block.Attached,"Held ball bulldozed construction");item.held=false;
   var arch=site.blocks.First(b=>b.Shape==ConstructionShape.Arch);Isolate(arch);Require(site.Drop(arch,site.World(new Vector3(0,arch.size.y*.5f,-12)),site.transform.rotation),"Arch stage failed");Launch(arch,3);ball.Advance(.02f,false);var archProxy=contacts.Single(c=>c.Block==arch&&c.gameObject.activeSelf);Require(archProxy.GetComponents<BoxCollider>().Count(c=>c.enabled)==3&&!archProxy.GetComponent<MeshCollider>().enabled,"Arch opening replaced by solid box");
   var ramp=site.blocks.First(b=>b.Shape==ConstructionShape.Ramp);Isolate(ramp);Require(site.Drop(ramp,site.World(new Vector3(0,ramp.size.y*.5f,-12)),site.transform.rotation),"Ramp stage failed");Launch(ramp,3);ball.Advance(.02f,false);Require(contacts.Single(c=>c.Block==ramp&&c.gameObject.activeSelf).GetComponent<MeshCollider>().enabled,"Convex ramp shape missing");
   var support=site.blocks.First(b=>b.Shape==ConstructionShape.Brick);Isolate(support);site.Recipe=BuildRecipe.Bench;foreach(var p in ConstructionPatterns.Plan(BuildRecipe.Bench)){var b=site.blocks.First(b=>!b.Attached&&b.RecipePiece&&(b.Shape==ConstructionShape.Beam)==p.beam);b.gameObject.SetActive(true);b.Body.gameObject.SetActive(true);Require(site.Drop(b,site.World(p.position),site.transform.rotation),"Visit bench stage failed");}var visitor=actors[0].GetComponent<VillagerExploration>();var walker=visitor.GetComponent<IslandNavigator>();slice.GetComponentInChildren<VillageFamilies>().ResetWorld();Require(nav.Sample(site.World(new Vector3(0,0,-12)),walker.profile,12,out var foot),"No visit stage");visitor.transform.position=nav.ProjectFoot(foot,walker.profile);walker.ResetRoute();Require(visitor.TryStructure(site),"Visit refused completed bench");int disappointments=actors[0].Memory.buildDisappointments;support=site.blocks.First(b=>b.Attached&&b.Shape==ConstructionShape.Brick);Launch(support,24);for(int i=0;i<100&&site.RecipeComplete;i++)Step();Require(!site.RecipeComplete,"Ball did not break the visited bench");visitor.Tick(.1f,false);Require(site.Visitor==null&&actors[0].Memory.buildDisappointments==disappointments+1,"Native villager visit did not react to knockdown");
   Debug.Log("BWVR_KNOCKDOWN_PASS: real ball-scene contacts push loose pieces and detach hard-hit snaps, gentle snap protection, bounded 16-proxy pool, held/pause guards, captured detached geometry, native arch/ramp collider fidelity and interrupted villager-use reaction");
  }finally{item.held=false;ball.ReturnHome();for(int i=0;i<site.blocks.Count;i++){site.blocks[i].Item.held=false;site.blocks[i].gameObject.SetActive(active[i]);site.blocks[i].Body.gameObject.SetActive(physicsActive[i]);}site.Recipe=recipe;site.Restore(geometry);site.Paused=paused;for(int i=0;i<actors.Length;i++)actors[i].transform.position=actorAt[i];god.Interrupt("Knockdown QA complete");god.transform.position=godAt;god.GetComponent<IslandNavigator>().ResetRoute();field.SetValue(slice,original);}
 }
}
}
